namespace editor {struct EditorDocumentTestAccess {
    static auto& Session(EditorLayer& e,Application& app){auto* s=e.EnsureMaterialSession(app);if(!s)throw std::runtime_error("missing material session");return *s;}
    static void Edit(EditorLayer& e,Application& app,const std::function<void(MaterialResource&)>& change){auto& s=Session(e,app);s.transaction=s.draft;change(s.draft);e.FinishMaterialEdit(app);}
    static bool Save(EditorLayer& e,Application& a){return e.SaveMaterialDraft(a);}
    static bool Reload(EditorLayer& e,Application& a){return e.ReloadMaterialDraft(a);}
    static void Undo(EditorLayer& e,Application& a,bool redo=false){e.UndoMaterialEdit(a,redo);}
    static auto Image(EditorLayer& e){return e.m_MaterialPreviewImage;}
    static auto Probes(EditorLayer& e){return e.m_MaterialPathProbes;}
    static auto UpdateMs(EditorLayer& e){return e.m_MaterialUpdateMs;}
};}
struct NativeMaterialDrop {
    AssetPayload payload{};bool active=false;
    static void Source(ImGuiContext*,ImGuiContextHook* hook){auto& d=*static_cast<NativeMaterialDrop*>(hook->UserData);if(d.active&&ImGui::BeginDragDropSource(ImGuiDragDropFlags_SourceExtern|ImGuiDragDropFlags_SourceNoPreviewTooltip)){ImGui::SetDragDropPayload("WHISP_ASSET",&d.payload,sizeof(d.payload));ImGui::EndDragDropSource();}}
};
static void Bitmap(const std::filesystem::path& path,unsigned char r,unsigned char g,unsigned char b){unsigned char data[58]={0x42,0x4d,58,0,0,0,0,0,0,0,54,0,0,0,40,0,0,0,1,0,0,0,1,0,0,0,1,0,24};data[34]=4;data[54]=b;data[55]=g;data[56]=r;std::ofstream file(path,std::ios::binary);file.write(reinterpret_cast<char*>(data),58);}
static unsigned checks=0;
static void Check(bool ok,const std::string& message){if(!ok)throw std::runtime_error(message);++checks;std::cerr<<checks<<": "<<message<<'\n';}
static std::string Bytes(const std::filesystem::path& path){std::ifstream f(path,std::ios::binary);return {std::istreambuf_iterator<char>(f),{}};}
static std::string Id(EditorLayer& e,const std::string& key){for(auto& d:e.Documents())if(d.key==key)return d.id;throw std::runtime_error("missing document");}
static bool Popup(){return ImGui::IsPopupOpen(nullptr,ImGuiPopupFlags_AnyPopupId|ImGuiPopupFlags_AnyPopupLevel);}
